    def save_delta_plan_file(self, plan_id, timeout=30):
        """
        apparently, `pe_api.upload_file` saves a file in /tmp and returns its path
        """
        if self.get_delta_plan_info(plan_id).is_changed:
            return self.pe_api.upload_file(self._request_for_delta_plan_file_name(plan_id, timeout=timeout))
        else:
            raise NegativeApiResponse(f"Requested delta-plan {plan_id} has no changes. "
                                      f"\nPlease make changes to plan to enable download operation.")

    def get_delta_plan_info(self, plan_id):
        return self.pe_api.get_delta_plan_info(plan_id)

    def _request_for_delta_plan_file_name(self, plan_id, timeout=30):
        action_id = self._generate_delta_plan_file(plan_id, timeout=30)
        return self._get_delta_plan_file_name(plan_id, action_id, timeout=timeout)

    def _generate_delta_plan_file(self, plan_id, timeout=30):
        plan_upload_options = PlanUploadOptions(delta_change_only=True)
        gen_deltaplan_res = self.pe_api.generate_delta_plan_file_for_uploading(plan_id=plan_id,
                                                                               plan_upload_options=plan_upload_options,
                                                                               _request_timeout=timeout)
        if gen_deltaplan_res.status == 'ongoing':
            return gen_deltaplan_res.action_id

        raise WrongApiResponseStatus(f"Request status for generate plan response {gen_deltaplan_res.status}")

    def _get_delta_plan_file_name(self, plan_id, action_id, interval=1, timeout=20):
        end_time = time.time() + timeout
        while time.time() < end_time:
            get_action_state_res = self.pe_api.get_action_state_of_uploading_delta_plan_file(plan_id=plan_id,
                                                                                             action_id=action_id,
                                                                                             _request_timeout=timeout)
            if get_action_state_res.status == 'success':
                return get_action_state_res.file_name
            else:
                time.sleep(interval)
        get_action_state_res = self.pe_api.get_action_state_of_uploading_delta_plan_file(plan_id=plan_id,
                                                                                         action_id=action_id,
                                                                                         _request_timeout=timeout)

        raise WrongApiResponseStatus(f"Request status for get action state response {get_action_state_res.status}")

