    def get_local_snapshot(self, directory, request_timeout=30, operation_timeout=600.0, compressed=True, sdl_components=None,
                           include_sdl_history_recordings=False, coverage='full', filter_regx=None):
        operation_id = self.local_client.trigger_local_snapshot(coverage=coverage,
                                                                originator='EM',
                                                                sdl_components=sdl_components,
                                                                include_sdl_history_recordings=include_sdl_history_recordings,
                                                                filter_regx=filter_regx)['operationId']
        start_time = time.time()
        snapshot_path = save_snapshot(instance=self,
                                      start_time=start_time,
                                      operation_id=operation_id,
                                      operation_timeout=operation_timeout,
                                      directory=directory,
                                      compressed=compressed,
                                      request_timeout=request_timeout)

        teardown_for_snapshot_collection(instance=self,
                                         start_time=start_time,
                                         operation_id=operation_id,
                                         request_timeout=request_timeout,
                                         operation_timeout=operation_timeout)

        return snapshot_path

