    def plan_validation(self, plan_id, wait_for_completion=False, timeout=30):
        operation = self.pe_api.validate_staged_plan(plan_id)

        if wait_for_completion:
            method_name = "get_validate_staged_plan_action"

            return poll_status(instance=self.pe_api, method_name=method_name,
                               action_id=operation.action_id, timeout=timeout,
                               plan_id=plan_id)

        return operation

