    def get_local_snapshot_by_id(self, directory, operation_id, request_timeout=None, operation_timeout=600.0,
                                 compressed=True):
        start_time = time.time()
        try:
            snapshot_path = save_snapshot(instance=self,
                                          start_time=start_time,
                                          operation_id=operation_id,
                                          operation_timeout=operation_timeout,
                                          directory=directory,
                                          compressed=compressed)
        except ApiException as err:
            if err.status == 404:
                raise SnapshotOperationIdNotFound(f"Snapshot with ID {operation_id} is not found")
            else:
                raise

        teardown_for_snapshot_collection(instance=self,
                                         start_time=start_time,
                                         operation_id=operation_id,
                                         operation_timeout=operation_timeout,
                                         request_timeout=request_timeout)

        return snapshot_path

